 const delta=(v,d=0)=>(v>0?'+':'')+fmt(v,d);
 function alternativesHTML(){if(!alternatives.length)return '';const list=alternatives.filter((r,i,a)=>a.findIndex(q=>q.o.typology===r.o.typology&&q.o.axis===r.o.axis&&q.o.stair===r.o.stair&&Math.abs((q.achieved||0)-(r.achieved||0))<.001)===i);return `<section class="ex-alternatives"><div class="ex-section-head"><span class="ex-eyebrow">STARTING GEOMETRIES</span><span>${alternatives.length} bounded candidates · density order</span></div><p class="ex-note">Massing, circulation and cores only. Unit fitting and travel distances are generated after selecting a starting point.</p><div class="ex-option-grid">${list.map(r=>{const i=alternatives.indexOf(r);return `<button class="ex-option" data-alt="${i}">${r.ok?V.plan(r,{W:320,H:250,coreOnly:true,extent:{W:last.context.bounds.w,D:last.context.bounds.h},title:'CORE STUDY'}):'<div class="ex-no-plan">Does not fit</div>'}<b>${E.names[r.o.typology]} · ${r.o.axis==='x'?'frontage':'depth'}</b><span>${esc({two:'Two interior stairs',external:'Two exterior stairs',one:'One exit · experimental',scissor:'Scissor · experimental'}[r.o.stair])}</span><span>${r.ok?`${fmt(r.achieved,2)} FSR · ${fmt(r.countable,0)} m²`:'Geometry blocked'}</span><small>${esc(r.ok?(r.flags[0]||'Spatial starting point; code review outstanding'):r.errors[0])}</small></button>`;}).join('')}</div></section>`;}
 // ---------- Plan editing aids: full screen, core snapping, dimensions, nudge, redo, selection card, ghost preview, warnings, options ----------
